&=\frac{10def(d^2f+d^2e-ef^2-e^2f)+6d(d^2e^3+d^2f^3-e^4f-ef^4)+4(d^4ef-e^3f^3)+2(d^4e^2+d^4f^2-e^2f^4-e^4f^2)}{(f+d)(d+e)(e^2+f^2)(d^2-ef)},
