def sgnstr(x):
    if x>=0:
        return str(x)
    else:
        return '('+str(x)+')'
def express(a):
    if len(a)==1:
        return str(a[0])
    if len(a)>1:
        return '('+express([a[i]-a[-1] for i in range(len(a)-1)])+')x(0.5±0.5)+'+sgnstr(a[-1])
