draw(K--B--C,heavyblue);
draw(circumcircle(F,E,M),linewidth(1)+lightolive);
draw(circumcircle(Y,D,M),linewidth(1)+lightgreen);
/* name objects*/
dot(A); label(" $A$ ", A, dir(90));
dot(B); label(" $B$ ", B, dir(220));
